// Projects shown on /projects.
//
// Two kinds:
//  - Interactive pages: a self-contained page at public/projects/{slug}/index.html.
//  - Videos: hosted on YouTube and embedded. Add a `video` block below with the YouTube id
//    (the part after youtu.be/), and put a poster at public/projects/{slug}/poster.jpg
//    (used for link previews). The watch page at /projects/{slug}/ is generated by
//    src/pages/projects/[slug].astro. Without a `youtube` id the page falls back to a
//    self-hosted file at public/projects/{slug}/video.mp4.
//
// Both kinds need a card thumbnail at src/images/projects/{slug}.jpg.
// To add one: drop in the files and add an entry here (order = display order).
export interface Project {
  slug: string;
  title: string;
  kind: string;      // small label above the title
  summary: string;   // shown on the card
  video?: {
    youtube?: string;      // YouTube video id, e.g. "aTlCl1YAajo"
    duration: string;      // shown on the card and watch page, e.g. "24 min"
    about: string[];       // paragraphs under the player
    covers?: string[];     // short list of what the video walks through
    note?: string;         // small print (how it was made, etc.)
  };
}

